// Savikainos helperis (kaip snippet 550: _cost_price -> _vf_cost -> _zb_cost)
if (!function_exists('petshop_bf_get_cost')) {
function petshop_bf_get_cost($pid) {
    $cost = get_post_meta($pid, '_cost_price', true);
    if ($cost === '' || $cost === false || $cost === null) $cost = get_post_meta($pid, '_vf_cost', true);
    if ($cost === '' || $cost === false || $cost === null) $cost = get_post_meta($pid, '_zb_cost', true);
    return ($cost !== '' && $cost !== false && $cost !== null) ? (float) $cost : null;
}
}

add_action('wp_ajax_petshop_search_products', function() {
    check_ajax_referer('petshop_rinkinio_nonce', 'nonce');
    $term = sanitize_text_field($_GET['term'] ?? '');
    $browse = (($_GET['browse'] ?? '') === '1'); // rodyti visus tinkamus (be paieskos termino)
    $source_cat = sanitize_text_field($_GET['source_cat'] ?? ''); // kategorijos filtras (slug)
    $warehouse = sanitize_text_field($_GET['warehouse'] ?? ''); // '', 'vf', 'zb', 'av'
    if (!$browse && strlen($term) < 2) { wp_send_json([]); return; }

    $tax_query = array('relation' => 'AND',
        array('taxonomy'=>'product_type', 'field'=>'slug', 'terms'=>array('simple')),
    );
    if ($source_cat) {
        $tax_query[] = array('taxonomy'=>'product_cat', 'field'=>'slug', 'terms'=>$source_cat);
    }

    // Sandelio filtras (meta_query) - kaip snippet 550
    $meta_query = array();
    if ($warehouse === 'vf') {
        $meta_query[] = array('key'=>'_vf_enabled', 'value'=>'yes');
    } elseif ($warehouse === 'zb') {
        $meta_query[] = array('key'=>'_zb_enabled', 'value'=>'yes');
    } elseif ($warehouse === 'av') {
        // AV (nuosavas) = NEI VF NEI ZB dropship
        $meta_query['relation'] = 'AND';
        $meta_query[] = array('relation'=>'OR',
            array('key'=>'_vf_enabled', 'compare'=>'NOT EXISTS'),
            array('key'=>'_vf_enabled', 'value'=>'yes', 'compare'=>'!=')
        );
        $meta_query[] = array('relation'=>'OR',
            array('key'=>'_zb_enabled', 'compare'=>'NOT EXISTS'),
            array('key'=>'_zb_enabled', 'value'=>'yes', 'compare'=>'!=')
        );
    }

    $args = array(
        'post_type' => 'product',
        'post_status' => 'publish',
        'posts_per_page' => $browse ? 150 : 25,
        'tax_query' => $tax_query,
    );
    if (!empty($meta_query)) { $args['meta_query'] = $meta_query; }
    if (strlen($term) >= 2) { $args['s'] = $term; }
    if ($browse) { $args['orderby'] = 'title'; $args['order'] = 'ASC'; }
    // Taip pat ieškom pagal SKU (tik jei ne browse)
    $by_sku = (!$browse && $term) ? wc_get_product_id_by_sku($term) : 0;

    $query = new WP_Query($args);
    $results = array();
    $seen = array();

    // Pirma SKU match
    if ($by_sku) {
        $p = wc_get_product($by_sku);
        if ($p && $p->get_status() === 'publish' && $p->is_type('simple')) {
            $img = wp_get_attachment_image_url($p->get_image_id(), 'thumbnail') ?: '';
            $results[] = array(
                'id' => $p->get_id(),
                'text' => $p->get_name() . ' (SKU: ' . $p->get_sku() . ')',
                'price' => (float) $p->get_price(),
                'cost' => petshop_bf_get_cost($p->get_id()),
                'stock' => $p->get_stock_quantity(),
                'stock_status' => $p->get_stock_status(),
                'image' => $img,
            );
            $seen[$by_sku] = true;
        }
    }

    if ($query->have_posts()) {
        while ($query->have_posts()) {
            $query->the_post();
            $pid = get_the_ID();
            if (isset($seen[$pid])) continue;
            $p = wc_get_product($pid);
            if (!$p) continue;
            $img = wp_get_attachment_image_url($p->get_image_id(), 'thumbnail') ?: '';
            $results[] = array(
                'id' => $p->get_id(),
                'text' => $p->get_name() . ' (SKU: ' . $p->get_sku() . ')',
                'price' => (float) $p->get_price(),
                'cost' => petshop_bf_get_cost($p->get_id()),
                'stock' => $p->get_stock_quantity(),
                'stock_status' => $p->get_stock_status(),
                'image' => $img,
            );
        }
        wp_reset_postdata();
    }
    wp_send_json($results);
});

