            var sourceCat = catFilter ? catFilter.value : '';
            var url = ajaxurl + '?action=petshop_search_products&nonce=' + nonce
                + '&term=' + encodeURIComponent(term)
                + '&source_cat=' + encodeURIComponent(sourceCat)
                + '&warehouse=' + encodeURIComponent(currentWarehouse)
                + (browse ? '&browse=1' : '');
            searchResults.innerHTML = '<div style="padding:10px;color:#999;">Kraunama…</div>';
            searchResults.style.display = 'block';
            fetch(url).then(function(r){ return r.json(); }).then(function(data){
                searchResults.innerHTML = '';
                if (!data.length) {
                    searchResults.innerHTML = '<div style="padding:8px;color:#999;">Nerasta</div>';
                    return;
                }
                // Virsutine juosta: pazymeti visus + prideti pazymetus + uzdaryti
                var bar = document.createElement('div');
                bar.style.cssText = 'position:sticky;top:0;background:#f6f8f7;border-bottom:1px solid #ddd;padding:8px 12px;display:flex;gap:10px;align-items:center;z-index:2;';
