                    + '<button type="button" class="button button-primary" id="bf-add-checked" style="font-size:12px;height:26px;line-height:24px;">➕ Pridėti pažymėtus</button>'
                    + '<span style="flex:1;"></span>'
                    + '<button type="button" class="button" id="bf-close-res" style="font-size:12px;height:26px;line-height:24px;">Uždaryti</button>';
                searchResults.appendChild(bar);

                data.forEach(function(p) {
                    var already = components.some(function(c){ return c.id === p.id; });
                    var div = document.createElement('div');
                    div.style.cssText = 'padding:8px 12px;border-bottom:1px solid #eee;display:flex;align-items:center;gap:8px;' + (already ? 'opacity:0.4;' : '');
                    var chk = already ? '<span style="width:16px;display:inline-block;color:#4caf50;">✓</span>'
                        : '<input type="checkbox" class="bf-chk" data-id="'+p.id+'">';
                    div.innerHTML = chk
                        + (p.image ? '<img src="'+p.image+'" style="width:32px;height:32px;object-fit:contain;border-radius:4px;">' : '<span style="width:32px;"></span>')
                        + '<div style="flex:1;"><div style="font-size:13px;">'+p.text+(p.stock!==null&&p.stock<=0?' <span style=\'color:#c00;font-size:11px;\'>(nėra likučio)</span>':'')+'</div>'
                        + '<div style="font-size:11px;color:#666;">Pard.: '+p.price.toFixed(2)+' € | Savikaina: '+(p.cost!==null?p.cost.toFixed(2)+' €':'nėra')+' | Likutis: '+(p.stock !== null ? p.stock : '∞')+'</div></div>'
                        + (already ? '' : '<button type="button" class="button bf-add-one" data-id="'+p.id+'" style="font-size:11px;height:24px;line-height:22px;">Pridėti</button>');
                    // saugom produkto duomenis
                    div._pdata = p;
                    searchResults.appendChild(div);
                    var addBtn = div.querySelector('.bf-add-one');
                    if (addBtn) addBtn.addEventListener('click', function(){ addComponent(p); div.style.opacity='0.4'; this.remove(); var c=div.querySelector('.bf-chk'); if(c) c.replaceWith(document.createTextNode('✓')); });
                });

                // Pazymeti visus
                var chkAll = searchResults.querySelector('#bf-chk-all');
                if (chkAll) chkAll.addEventListener('change', function(){
                    var ck = this.checked;
                    searchResults.querySelectorAll('.bf-chk').forEach(function(c){ c.checked = ck; });
                });
                // Prideti pazymetus
                var addChecked = searchResults.querySelector('#bf-add-checked');
                if (addChecked) addChecked.addEventListener('click', function(){
                    var added = 0;
                    searchResults.querySelectorAll('.bf-chk:checked').forEach(function(c){
                        var row = c.closest('div'); if (!row || !row._pdata) return;
                        addComponent(row._pdata); added++;
                    });
                    if (added > 0) { searchResults.style.display = 'none'; searchInput.value = ''; }
                });
                var closeBtn = searchResults.querySelector('#bf-close-res');
                if (closeBtn) closeBtn.addEventListener('click', function(){ searchResults.style.display = 'none'; });
            });
        }

        // Paieska rasant
        searchInput.addEventListener('input', function() {
            clearTimeout(searchTimer);
            var val = this.value.trim();
            if (val.length < 2) { searchResults.style.display = 'none'; return; }
            searchTimer = setTimeout(function(){ runSearch(val, false); }, 300);
        });
        // Rodyti visus tinkamus
        if (browseBtn) browseBtn.addEventListener('click', function(){ runSearch('', true); });

        document.addEventListener('click', function(e) {
            if (!searchResults.contains(e.target) && e.target !== searchInput && e.target !== browseBtn) {
                searchResults.style.display = 'none';
            }
        });

        function addComponent(product) {
            components.push({ id: product.id, name: product.text, price: parseFloat(product.price), cost: (product.cost!==null && product.cost!==undefined ? parseFloat(product.cost) : null), qty: 1, stock: product.stock, image: product.image });
