            var totalQty = 0, totalPrice = 0, totalCost = 0, anyCostMissing = false;
            components.forEach(function(c){
                totalQty += c.qty;
                totalPrice += c.price * c.qty;
                if (c.cost !== null && c.cost !== undefined) totalCost += c.cost * c.qty; else anyCostMissing = true;
            });
            var perUnitPrice = (bundlePrice > 0 && totalQty > 0) ? (bundlePrice / totalQty) : 0;

            var table = document.createElement('table');
            table.className = 'widefat striped';
            table.innerHTML = '<thead><tr><th style="width:40px;"></th><th>Produktas</th><th style="width:90px;">Pard. kaina</th><th style="width:90px;">Savikaina</th><th style="width:110px;">Marža/vnt*</th><th style="width:70px;">Kiekis</th><th style="width:40px;"></th></tr></thead>';
            var tbody = document.createElement('tbody');

            components.forEach(function(c, i) {
                var tr = document.createElement('tr');
                var hasCost = (c.cost !== null && c.cost !== undefined);
