                    if (margin < 0) { marginCell = '<strong style="color:#c00;">' + margin.toFixed(2) + ' € ❌</strong>'; rowStyle='background:#fff0f0;'; }
                    else { marginCell = '<span style="color:#2a8;">' + margin.toFixed(2) + ' € ✅</span>'; }
                }
