            compContainer.querySelectorAll('.bf-remove-btn').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    components.splice(parseInt(this.dataset.idx), 1);
                    renderComponents();
                });
            });

            // === Rinkinio santrauka (kaip 550 Pool santrauka) ===
            var prices = components.map(function(c){ return c.price; });
            var costs = components.filter(function(c){ return c.cost!==null && c.cost!==undefined; }).map(function(c){ return c.cost; });
            var avgPricePerUnit = totalQty > 0 ? (totalPrice / totalQty) : 0;
            var avgCostPerUnit = (totalQty > 0 && !anyCostMissing) ? (totalCost / totalQty) : null;
            var maxPrice = prices.length ? Math.max.apply(null, prices) : 0;
            var minPrice = prices.length ? Math.min.apply(null, prices) : 0;

            var sh = '<div style="background:#eef5fb;border:1px solid #cfe2f3;border-radius:8px;padding:14px;">';
            sh += '<strong style="font-size:14px;">📊 Rinkinio santrauka (' + totalQty + ' vnt.)</strong>';
            sh += '<div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:10px;font-size:13px;">';
            sh += '<div>Visų suma (pard.):<br><strong style="font-size:16px;">' + totalPrice.toFixed(2) + ' €</strong></div>';
