// Petshop Susidėjimo Rinkinio Vitrina v19
// v16: gram/size mygtukai dinamiškai perkuriami
// v17: "be gramatūros" režimas; v18: FIX redagavimo srautas (konfigą iš tėvinio)
// v19: grupių bloko antraštė iš _petshop_choice_group_label (kramtalams "Šuns dydis"); default "Rinkinio tipas"
// Tėvinio produkto puslapyje renderina GRAMATŪRA/DYDIS mygtukus + visas paslėptas MnM formas.
// JS perjungia matomą formą. Klientas mato vientisą konstruktorių.
// (A) Veikia ir ant PASLĖPTŲ produktų (kai atidaromi per "Keisti pasirinkimus") — rodo pilną konstruktorių.

// Helper: grąžina choice info bet kuriam produktui (tėviniam arba paslėptam)
// Normalizuoja config į v2 grupių struktūrą: {group_key: {label, gramaturos: {gram: {size: {product_id, price}}}}}
// v1 (senas, {gram:{size}}) automatiškai įvyniojamas į vieną numatytą grupę "_default".
// Grąžina: ['parent_id', 'config'(normalized), 'is_multigroup'=>bool, 'init_group', 'init_gram', 'init_size', 'is_hidden']
function petshop_normalize_choice_config($config) {
    if (!is_array($config) || empty($config)) return null;
    // v2 atpažinimas: pirmas elementas turi 'gramaturos' raktą
    $first = reset($config);
    $is_v2 = is_array($first) && isset($first['gramaturos']);
    if ($is_v2) {
        return array('config' => $config, 'is_multigroup' => (count($config) > 1));
    }
    // v1 → įvyniojam į vieną grupę
    $wrapped = array('_default' => array('label' => '', 'gramaturos' => $config));
    return array('config' => $wrapped, 'is_multigroup' => false);
}

function petshop_get_choice_info($pid) {
    if (!$pid) return null;
    // 1. Tėvinis choice?
    if (get_post_meta($pid, '_petshop_is_choice_bundle', true) === 'yes') {
        $raw = json_decode(get_post_meta($pid, '_petshop_choice_config', true), true);
        $norm = petshop_normalize_choice_config($raw);
        if (!$norm) return null;
        return [
            'parent_id'=>$pid, 'config'=>$norm['config'], 'is_multigroup'=>$norm['is_multigroup'],
            'init_group'=>null, 'init_gram'=>null, 'init_size'=>null, 'is_hidden'=>false,
            'no_gram'=>(get_post_meta($pid,'_petshop_choice_no_gram',true)==='yes')
        ];
    }
    // 2. Paslėptas choice? (turi atgalinę nuorodą į tėvinį)
    $parent = get_post_meta($pid, '_petshop_choice_parent', true);
    if ($parent) {
        $raw = json_decode(get_post_meta($parent, '_petshop_choice_config', true), true);
        $norm = petshop_normalize_choice_config($raw);
        if (!$norm) return null;
        return [
            'parent_id' => intval($parent),
            'config' => $norm['config'],
            'is_multigroup' => $norm['is_multigroup'],
            'init_group' => get_post_meta($pid, '_petshop_choice_group', true) ?: '_default',
            'init_gram' => get_post_meta($pid, '_petshop_choice_gram', true),
            'init_size' => get_post_meta($pid, '_petshop_choice_size', true),
            'is_hidden' => true,
            'hidden_id' => $pid,
            'no_gram' => (get_post_meta(intval($parent),'_petshop_choice_no_gram',true)==='yes')
        ];
    }
    return null;
}

// Įjungiam tėviniams IR paslėptiems choice produktams
add_action('woocommerce_before_single_product', function() {
    global $product;
    if (!$product) return;
    $pid = is_object($product) ? $product->get_id() : 0;
    $info = petshop_get_choice_info($pid);
    if (!$info) return;
    $GLOBALS['petshop_is_choice_page'] = $pid;
    $GLOBALS['petshop_choice_info'] = $info;
});

// Body klasė choice puslapiams (fullwidth, kai nėra nuotraukos)
add_filter('body_class', function($classes) {
    if (!is_product()) return $classes;
    global $post;
    if (!$post) return $classes;
    $info = petshop_get_choice_info($post->ID);
    if (!$info) return $classes;
    $classes[] = 'petshop-choice-page';
    $classes[] = 'petshop-choice-fullwidth'; // visada fullwidth (nuotrauka slepiama)
    return $classes;
});

// Pagrindinis renderinimas — vietoj standartinio add_to_cart
add_action('woocommerce_single_product_summary', function() {
    global $product;
    if (!$product) return;
    $current_pid = $product->get_id();
    $info = petshop_get_choice_info($current_pid);
    if (!$info) return;

    $parent_id = $info['parent_id'];
    $config = $info['config']; // {group_key: {label, gramaturos: {gram: {size: {product_id, price}}}}}
    $is_multigroup = $info['is_multigroup'];
    $no_gram = !empty($info['no_gram']); // v17: skanėstų režimas be gramatūros
    $group_label = get_post_meta($parent_id, '_petshop_choice_group_label', true); // v19
    if (!$group_label) $group_label = 'Rinkinio tipas';

    // Grupės
    $group_keys = array_keys($config);

    // Numatytoji grupė: jei redaguojam paslėptą — jo grupė; kitaip pirma
    if ($info['is_hidden'] && $info['init_group'] && isset($config[$info['init_group']])) {
        $default_group = $info['init_group'];
    } else {
        $default_group = $group_keys[0];
    }

    // Gramatūros/dydžiai iš NUMATYTOSIOS grupės
    $group_gram = $config[$default_group]['gramaturos'];
    $gramaturos = array_keys($group_gram);
    sort($gramaturos, SORT_NUMERIC);
    $first_gram = $gramaturos[0];
    $dydziai = array_keys($group_gram[$first_gram]);
    sort($dydziai, SORT_NUMERIC);

    // Numatytasis dydis/svoris: jei redaguojam — iš paslėpto; kitaip pirma gram + vidurinis dydis
    if ($info['is_hidden'] && $info['init_gram'] && $info['init_size']) {
        $default_gram = $info['init_gram'];
        $default_size = $info['init_size'];
    } else {
        $default_gram = $gramaturos[0];
        $default_size = isset($dydziai[1]) ? $dydziai[1] : $dydziai[0];
    }

    echo '<div class="petshop-choice-constructor" data-parent="'.esc_attr($parent_id).'">';

    // Trumpas paaiškinimas
    $parent_obj = wc_get_product($parent_id);
    $short = $parent_obj ? $parent_obj->get_short_description() : '';
    if ($short) {
        echo '<p class="psc-intro">'.wp_kses_post($short).'</p>';
    } else {
        echo '<p class="psc-intro">'.($no_gram ? 'Pasirink kiek pakelių ir susidėk norimus skanėstus į vieną rinkinį.' : 'Pasirink konservų dydį, rinkinio dydį ir susidėk norimus skonius į vieną dėžę.').'</p>';
    }

    // Grid wrapper — kairė (konstruktorius) + dešinė (suvestinė)
    echo '<div class="psc-layout">';
    echo '<div class="psc-main">';

    // === Grupės mygtukai (tik jei kelios grupės) ===
    if ($is_multigroup) {
        echo '<div class="psc-section"><div class="psc-label">'.esc_html($group_label).'</div><div class="psc-btn-row psc-group-row">';
        foreach ($group_keys as $gk) {
            $active = ($gk === $default_group) ? ' psc-active' : '';
            $glabel = $config[$gk]['label'] ?: $gk;
            echo '<button type="button" class="psc-btn psc-group-btn'.$active.'" data-group="'.esc_attr($gk).'">'
                . '<span class="psc-btn-big">'.esc_html($glabel).'</span>'
                . '</button>';
        }
        echo '</div></div>';
    }

    // === Konservo dydis mygtukai (rodo numatytosios grupės gramatūras; JS atnaujins) ===
    // v17: be gramatūros režime paslepiam sekciją (mygtukas lieka, kad JS nustatytų currentGram)
    $gram_style = $no_gram ? ' style="display:none;"' : '';
    echo '<div class="psc-section"'.$gram_style.'><div class="psc-label">Konservo dydis</div><div class="psc-btn-row psc-gram-row">';
    foreach ($gramaturos as $g) {
        $active = ($g == $default_gram) ? ' psc-active' : '';
        echo '<button type="button" class="psc-btn psc-gram-btn'.$active.'" data-gram="'.esc_attr($g).'">'
            . '<span class="psc-btn-big">'.esc_html($g).' g</span>'
            . '</button>';
    }
    echo '</div></div>';

    // === Rinkinio dydis mygtukai ===
    echo '<div class="psc-section"><div class="psc-label">Rinkinio dydis</div><div class="psc-btn-row psc-size-row">';
    foreach ($dydziai as $s) {
        $active = ($s == $default_size) ? ' psc-active' : '';
        $box_price = $group_gram[$default_gram][$s]['price'];
        $per_unit = $box_price / intval($s);
        echo '<button type="button" class="psc-btn psc-size-btn'.$active.'" data-size="'.esc_attr($s).'">'
            . '<span class="psc-btn-big">'.esc_html($s).' vnt.</span>'
            . '<span class="psc-btn-small psc-per-unit">'.number_format($per_unit, 2, ',', ' ').' €/vnt.</span>'
            . '</button>';
    }
    echo '</div></div>';

    // === Antraštė virš konservų sąrašo ===
    echo '<div class="psc-cans-header">';
    echo '<div class="psc-cans-title">'.($no_gram ? 'Pasirink skanėstus' : 'Pasirink konservus').'</div>';
    echo '<p class="psc-cans-note">Galite rinktis skirtingus skonius arba kelis vienodus — svarbu surinkti pasirinktą kiekį.</p>';
    echo '</div>';

    // === Visos paslėptos MnM formos (VISŲ grupių — JS rodo tik aktyvią) ===
    echo '<div class="psc-forms">';
    foreach ($config as $gkey => $gdata) {
        foreach ($gdata['gramaturos'] as $gram => $sizes) {
            foreach ($sizes as $size => $sinfo) {
                $hidden_id = $sinfo['product_id'];
                $hidden_product = wc_get_product($hidden_id);
                if (!$hidden_product) continue;
                $is_default = ($gkey === $default_group && $gram == $default_gram && $size == $default_size);
                $style = $is_default ? '' : 'style="display:none;"';
                echo '<div class="psc-form" data-group="'.esc_attr($gkey).'" data-gram="'.esc_attr($gram).'" data-size="'.esc_attr($size).'" '.$style.'>';
                $GLOBALS['product'] = $hidden_product;
                do_action('woocommerce_' . $hidden_product->get_type() . '_add_to_cart');
                $GLOBALS['product'] = wc_get_product($parent_id);
                echo '</div>';
            }
        }
    }
    echo '</div>'; // .psc-forms

    echo '</div>'; // .psc-main

    // Dešinė suvestinė
    $default_price = $group_gram[$default_gram][$default_size]['price'];
    echo '<div class="psc-sidebar"><div class="psc-summary">';
    echo '<div class="psc-summary-title">Jūsų rinkinys</div>';
    echo '<div class="psc-summary-row"><span>Pasirinkta</span><span class="psc-sum-selected" data-target="'.esc_attr($default_size).'">0 / '.esc_html($default_size).'</span></div>';
    echo '<div class="psc-summary-row"><span>Liko pasirinkti</span><span class="psc-sum-left">'.esc_html($default_size).'</span></div>';
    echo '<div class="psc-progress"><div class="psc-progress-fill"></div></div>';
    echo '<div class="psc-summary-price-row"><span>Kaina</span><span class="psc-box-price">'.number_format($default_price, 2, ',', ' ').' €</span></div>';
    echo '<div class="psc-cta-slot"></div>';
    echo '</div></div>';

    echo '</div>'; // .psc-layout
    echo '</div>'; // .petshop-choice-constructor

    // === CSS ===
    ?>
