                <button type="button" id="pcf-custom-group-cancel" class="button-link" style="color:#c00;margin-left:6px;">atšaukti</button>
            </div>

            <div style="margin-top: 30px;">
                <button type="button" id="pcf-create" class="button button-primary button-large" disabled>Sukurti susidėjimo rinkinį</button>
                <span id="pcf-status" style="margin-left: 12px; font-style: italic;"></span>
