    <script>
    (function(){
        var nonce = '<?php echo esc_js($nonce); ?>';
        var ajaxurl = '<?php echo esc_js(admin_url('admin-ajax.php')); ?>';

        // Grupių modelis:
        // groups = [{key, label, filter, gramaturos:[{gram, sizes:[{size,price}], pool:[{id,text,price,cost}]}]}]
        var groups = [];

        // Grupių presetai (label + siūlomas filtras) — v10: priklauso nuo Pool šaltinio
        var PRESETS_DOG = [
            {key:'mix', label:'Mix', filter:''},
            {key:'jautrus', label:'Jautriam virškinimui', filter:'jautrus'},
            {key:'hipo', label:'Hipoalerginis', filter:'hipo'},
            {key:'mono', label:'Monoproteinas', filter:'mono'},
            {key:'be_grudu', label:'Be grūdų', filter:'be_grudu'}
        ];
        var PRESETS_CAT = [
            {key:'mix', label:'Mix', filter:''},
            {key:'isrankioms', label:'Išrankioms', filter:''},
            {key:'kaciukams', label:'Kačiukams', filter:''}
        ];
        // v14: kramtalams/skanėstams šunims — dydžio grupės (customer-relevant + vertės koherencija)
        var PRESETS_CHEW_DOG = [
            {key:'mazas', label:'Mažam šuniui', filter:''},
            {key:'vidutinis', label:'Vidutiniam šuniui', filter:''},
            {key:'didelis', label:'Dideliam šuniui', filter:''}
        ];
        function currentPresets(){
            var el = document.getElementById('pcf-source-cat');
            var src = el ? el.value : '';
            if (/katems/.test(src)) return PRESETS_CAT;
            if (noGram) return PRESETS_CHEW_DOG; // be-gramatūros šunų rinkinys (skanėstai/kramtalai) → dydžio grupės; kitiems vardams „+ Kita…"
            return PRESETS_DOG;
        }
        var FILTER_LABELS = {'':'Visi', 'mono':'Monoproteinas', 'be_grudu':'Be grūdų', 'jautrus':'Jautriam virškinimui', 'hipo':'Hipoalerginis'};

        var noGram = false; // v12: skanėstų režimas be gramatūros
        var groupsContainer = document.getElementById('pcf-groups');
        var createBtn = document.getElementById('pcf-create');
        var statusEl = document.getElementById('pcf-status');
        var resultEl = document.getElementById('pcf-result');

        // === Pridėti grupę (v8: preset mygtukai, ne prompt) ===
        function slugifyKey(s){ return s.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''); }
        function addGroup(key, label, filter){
            if (!key) { alert('Netinkamas grupės pavadinimas.'); return; }
            if (groups.some(function(g){return g.key===key;})) { alert('Tokia grupė jau yra.'); return; }
            // v15: pridėjus dydžio grupę — auto antraštė „Šuns dydis" (jei tuščia)
            if (['mazas','vidutinis','didelis'].indexOf(key) >= 0){
                var glEl = document.getElementById('pcf-group-label');
                if (glEl && !glEl.value.trim()) glEl.value = 'Šuns dydis';
            }
            groups.push({
                key: key,
                label: label,
                filter: filter || '',
                gramaturos: noGram
                    ? [{ gram:'std', sizes:[{size:5,price:0},{size:7,price:0},{size:10,price:0}], pool:[] }]
                    : [{ gram:'400', sizes:[{size:6,price:0},{size:12,price:0}], pool:[] }]
            });
            render();
        }
        function renderAddButtons(){
            var row = document.getElementById('pcf-add-group-row');
            row.innerHTML = '';
            var used = groups.map(function(g){return g.key;});
            currentPresets().forEach(function(p){
                if (used.indexOf(p.key) >= 0) return; // jau pridėta
                var b = document.createElement('button');
                b.type = 'button'; b.className = 'button button-secondary';
                b.textContent = '+ ' + p.label;
                b.onclick = function(){ addGroup(p.key, p.label, p.filter); };
                row.appendChild(b);
            });
            var kb = document.createElement('button');
            kb.type = 'button'; kb.className = 'button';
            kb.textContent = '+ Kita…';
            kb.onclick = function(){
                var cr = document.getElementById('pcf-custom-group-row');
                cr.style.display = (cr.style.display === 'none' || !cr.style.display) ? 'block' : 'none';
                if (cr.style.display === 'block') document.getElementById('pcf-custom-group-name').focus();
            };
            row.appendChild(kb);
        }
        document.getElementById('pcf-custom-group-add').onclick = function(){
            var n = document.getElementById('pcf-custom-group-name').value.trim();
            if (!n) return;
            addGroup(slugifyKey(n), n, '');
            document.getElementById('pcf-custom-group-name').value = '';
            document.getElementById('pcf-custom-group-row').style.display = 'none';
        };
        document.getElementById('pcf-custom-group-name').addEventListener('keydown', function(e){
            if (e.key === 'Enter') { e.preventDefault(); document.getElementById('pcf-custom-group-add').click(); }
        });
        document.getElementById('pcf-custom-group-cancel').onclick = function(){
            document.getElementById('pcf-custom-group-name').value = '';
            document.getElementById('pcf-custom-group-row').style.display = 'none';
        };
        renderAddButtons(); // init: rodyti preset mygtukus iškart
        // v12: be gramatūros jungiklis
        (function(){ var ng=document.getElementById('pcf-no-gram'); if(ng) ng.addEventListener('change', function(){ noGram=ng.checked; render(); }); })();
        // v10: keičiant Pool šaltinį — perpaišom presetus (katėms/šunims)
        (function(){ var sc=document.getElementById('pcf-source-cat'); if(sc) sc.addEventListener('change', renderAddButtons); })();

        // === v9: Pagrindinės nuotraukos parinkimas (WP media) ===
        var pcfMediaFrame = null;
        function pcfRenderImage(){
            var id = document.getElementById('pcf-image-id').value;
            var prev = document.getElementById('pcf-image-preview');
            var rm = document.getElementById('pcf-image-remove');
            var sel = document.getElementById('pcf-image-select');
            if (id && window._pcfImageUrl){
                prev.innerHTML = '<img src="'+window._pcfImageUrl+'" style="max-width:160px;height:auto;border:1px solid #ddd;border-radius:6px;">';
                rm.style.display = 'inline';
                sel.textContent = '📷 Keisti nuotrauką';
            } else {
                prev.innerHTML = '';
                rm.style.display = 'none';
                sel.textContent = '📷 Pasirinkti nuotrauką';
            }
        }
        document.getElementById('pcf-image-select').addEventListener('click', function(e){
            e.preventDefault();
            if (pcfMediaFrame){ pcfMediaFrame.open(); return; }
            pcfMediaFrame = wp.media({ title:'Rinkinio pagrindinė nuotrauka', button:{text:'Naudoti šią nuotrauką'}, multiple:false, library:{type:'image'} });
            pcfMediaFrame.on('select', function(){
                var att = pcfMediaFrame.state().get('selection').first().toJSON();
                document.getElementById('pcf-image-id').value = att.id;
                window._pcfImageUrl = (att.sizes && att.sizes.thumbnail) ? att.sizes.thumbnail.url : att.url;
                pcfRenderImage();
            });
            pcfMediaFrame.open();
        });
        document.getElementById('pcf-image-remove').addEventListener('click', function(e){
            e.preventDefault();
            document.getElementById('pcf-image-id').value = '';
            window._pcfImageUrl = '';
            pcfRenderImage();
        });

        function render(){
