                gh += '<button type="button" class="button-link pcf-del-group" data-gp="'+gpi+'" style="color:#c00;font-size:13px;">✕ pašalinti grupę</button>';
                gh += '</div>';

                // Grupės filtras (taikomas visai grupei — padeda atrinkti konservus)
                gh += '<div style="background:#f0f6fc;border:1px solid #cfe2f3;border-radius:6px;padding:10px 14px;margin-bottom:14px;">';
