                filters.forEach(function(f){
                    var isAct = ((grp.filter||'') === f[0]);
                    gh += '<button type="button" class="button pcf-gfilter'+(isAct?' button-primary':'')+'" data-gp="'+gpi+'" data-filter="'+f[0]+'" style="font-size:12px;padding:2px 10px;height:auto;">'+f[1]+'</button>';
                });
                gh += '</span></div>';
                // Sandėlio filtras (antra ašis — dera su tipu)
                gh += '<div style="margin-top:8px;"><strong style="font-size:13px;">Sandėlis:</strong> ';
                gh += '<span style="display:inline-flex;gap:6px;flex-wrap:wrap;margin-left:8px;vertical-align:middle;">';
                var warehouses = [['','Visi'],['vf','VF'],['zb','ZB'],['av','AV (nuosava)']];
                warehouses.forEach(function(w){
                    var isAct = ((grp.warehouse||'') === w[0]);
                    gh += '<button type="button" class="button pcf-gwh'+(isAct?' button-primary':'')+'" data-gp="'+gpi+'" data-wh="'+w[0]+'" style="font-size:12px;padding:2px 10px;height:auto;">'+w[1]+'</button>';
                });
                gh += '</span></div>';
                gh += '</div>';
                gbox.innerHTML = gh;

                // Kiekviena gramatūra grupėje
                grp.gramaturos.forEach(function(g, gi){
                    var box = document.createElement('div');
                    box.style.cssText = 'border:1px solid #ccc;border-radius:8px;padding:16px;margin-bottom:14px;background:#fafafa;';
                    var html = noGram
                        ? ''
                        : '<h3 style="margin-top:0;">'+g.gram+'g <button type="button" class="button-link pcf-del-gram" data-gp="'+gpi+'" data-gi="'+gi+'" style="color:#c00;font-size:13px;">✕ pašalinti gramatūrą</button></h3>';

                    // Dydžiai + kainos
                    html += '<div style="margin-bottom:12px;"><strong>'+(noGram?'Rinkinio dydis (pakuočių kiekis) ir kainos:':'Dydžiai ir dėžės kainos:')+'</strong><table style="margin-top:6px;"><tr><th style="padding:4px 12px;">Kiekis</th><th style="padding:4px 12px;">Dėžės kaina €</th><th style="padding:4px 12px;">€/vnt</th><th></th></tr>';
                    g.sizes.forEach(function(s, si){
                        var perUnit = s.price>0 ? (s.price/s.size).toFixed(2) : '—';
                        html += '<tr><td style="padding:4px 12px;"><input type="number" min="1" value="'+s.size+'" data-gp="'+gpi+'" data-gi="'+gi+'" data-si="'+si+'" class="pcf-size-qty" style="width:60px;"></td>'
                            + '<td style="padding:4px 12px;"><input type="number" step="0.01" min="0" value="'+(s.price||'')+'" data-gp="'+gpi+'" data-gi="'+gi+'" data-si="'+si+'" class="pcf-size-price" style="width:80px;" placeholder="0.00"></td>'
                            + '<td style="padding:4px 12px;color:#666;">'+perUnit+' €</td>'
                            + '<td><button type="button" class="button-link pcf-del-size" data-gp="'+gpi+'" data-gi="'+gi+'" data-si="'+si+'" style="color:#c00;">✕</button></td></tr>';
                    });
                    html += '</table><button type="button" class="button pcf-add-size" data-gp="'+gpi+'" data-gi="'+gi+'" style="margin-top:6px;">+ dydis</button></div>';

                    // Pool paieška
                    html += '<div><strong>Pool\'as ('+g.pool.length+' konservų):</strong>';
                    html += '<div style="position:relative;margin:8px 0;"><input type="text" class="pcf-search regular-text" data-gp="'+gpi+'" data-gi="'+gi+'" placeholder="🔍 Ieškoti '+(noGram?'skanėsto':g.gram+'g konservo')+' (filtras: '+(FILTER_LABELS[grp.filter||'']||'Visi')+')..." style="width:340px;" autocomplete="off"> <button type="button" class="button pcf-browse" data-gp="'+gpi+'" data-gi="'+gi+'" style="margin-left:6px;">📋 Rodyti visus tinkamus</button><div class="pcf-search-results" data-gp="'+gpi+'" data-gi="'+gi+'" style="position:absolute;z-index:1000;background:#fff;border:1px solid #ccc;max-height:340px;overflow-y:auto;width:600px;display:none;"></div></div>';

                    // Pool lentelė su marža
                    var refSize = g.sizes.find(function(s){return s.price>0;});
                    var perUnitPrice = refSize ? (refSize.price/refSize.size) : 0;
                    if (g.pool.length){
                        html += '<table class="widefat" style="margin-top:8px;"><thead><tr><th>Konservas</th><th>Pard. kaina</th><th>Savikaina</th><th>Marža/vnt*</th><th></th></tr></thead><tbody>';
                        g.pool.forEach(function(c, ci){
                            var cost = c.cost!==null ? c.cost : null;
                            var margin = (cost!==null && perUnitPrice>0) ? (perUnitPrice - cost) : null;
                            var marginCell, rowStyle='';
                            if (cost===null) { marginCell='<span style="color:#999;">nėra savikainos</span>'; }
                            else if (perUnitPrice<=0) { marginCell='<span style="color:#999;">įrašyk dydžio kainą ↑</span>'; }
                            else if (margin < 0) { marginCell='<strong style="color:#c00;">'+margin.toFixed(2)+' € ❌</strong>'; rowStyle='background:#fff0f0;'; }
                            else { marginCell='<span style="color:#2a8;">'+margin.toFixed(2)+' € ✅</span>'; }
                            html += '<tr style="'+rowStyle+'"><td>'+c.text+'</td><td>'+c.price.toFixed(2)+' €</td>'
                                + '<td>'+(cost!==null?cost.toFixed(2)+' €':'—')+'</td><td>'+marginCell+'</td>'
                                + '<td><button type="button" class="button-link pcf-del-pool" data-gp="'+gpi+'" data-gi="'+gi+'" data-ci="'+ci+'" style="color:#c00;">✕</button></td></tr>';
                        });
                        html += '</tbody></table>';
                        html += '<p class="description">* Marža/vnt pagal dėžės kainą '+(refSize?refSize.price+' €/'+refSize.size+' vnt = '+perUnitPrice.toFixed(2)+' €/vnt':'(nustatykite dydžio kainą)')+'</p>';

                        // Pool santrauka
                        var prices = g.pool.map(function(c){return c.price;});
                        var costs = g.pool.filter(function(c){return c.cost!==null;}).map(function(c){return c.cost;});
                        var avgPrice = prices.reduce(function(a,b){return a+b;},0) / prices.length;
                        var avgCost = costs.length ? costs.reduce(function(a,b){return a+b;},0)/costs.length : null;
                        var maxPrice = Math.max.apply(null, prices);
                        var minPrice = Math.min.apply(null, prices);
                        var maxCost = costs.length ? Math.max.apply(null, costs) : null;
                        var totalPrice = prices.reduce(function(a,b){return a+b;},0);
                        var totalCost = costs.length ? costs.reduce(function(a,b){return a+b;},0) : null;

                        html += '<div style="background:#eef5fb;border:1px solid #cfe2f3;border-radius:8px;padding:14px;margin-top:12px;">';
                        html += '<strong style="font-size:14px;">📊 Pool santrauka ('+g.pool.length+' konservų)</strong>';
                        html += '<div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:10px;font-size:13px;">';
                        html += '<div>Visų suma (pard.):<br><strong style="font-size:16px;">'+totalPrice.toFixed(2)+' €</strong></div>';
                        html += '<div>Visų suma (savik.):<br><strong style="font-size:16px;">'+(totalCost!==null?totalCost.toFixed(2)+' €':'—')+'</strong></div>';
                        html += '<div>Vid. pard. kaina/vnt:<br><strong style="font-size:16px;">'+avgPrice.toFixed(2)+' €</strong></div>';
                        html += '<div>Vid. savikaina/vnt:<br><strong style="font-size:16px;">'+(avgCost!==null?avgCost.toFixed(2)+' €':'—')+'</strong></div>';
                        html += '<div>Brangiausias:<br><strong>'+maxPrice.toFixed(2)+' €</strong></div>';
                        html += '<div>Pigiausias:<br><strong>'+minPrice.toFixed(2)+' €</strong></div>';
                        html += '</div>';

                        html += '<div style="margin-top:12px;border-top:1px solid #cfe2f3;padding-top:10px;">';
                        html += '<strong style="font-size:13px;">💡 Orientyras dėžės kainai:</strong>';
                        html += '<table style="margin-top:6px;font-size:13px;width:100%;"><tr style="color:#666;"><th style="text-align:left;padding:3px 8px;">Dydis</th><th style="text-align:left;padding:3px 8px;">Tavo kaina</th><th style="text-align:left;padding:3px 8px;">Atskirai (vid.)</th><th style="text-align:left;padding:3px 8px;">Marža/dėžė (vid.)</th><th style="text-align:left;padding:3px 8px;">Blogiausiu atveju*</th></tr>';
                        g.sizes.forEach(function(s){
                            if (s.price <= 0) return;
                            var separateAvg = avgPrice * s.size;
                            var marginAvg = avgCost!==null ? (s.price - avgCost*s.size) : null;
                            var marginWorst = maxCost!==null ? (s.price - maxCost*s.size) : null;
                            var worstCell = marginWorst!==null ? (marginWorst<0 ? '<strong style="color:#c00;">'+marginWorst.toFixed(2)+' € ❌</strong>' : '<span style="color:#2a8;">'+marginWorst.toFixed(2)+' € ✅</span>') : '—';
                            html += '<tr><td style="padding:3px 8px;">'+s.size+' vnt</td>'
                                + '<td style="padding:3px 8px;"><strong>'+s.price.toFixed(2)+' €</strong></td>'
                                + '<td style="padding:3px 8px;color:#666;">'+separateAvg.toFixed(2)+' €</td>'
                                + '<td style="padding:3px 8px;">'+(marginAvg!==null?marginAvg.toFixed(2)+' €':'—')+'</td>'
                                + '<td style="padding:3px 8px;">'+worstCell+'</td></tr>';
                        });
                        html += '</table>';
                        html += '<p style="font-size:11px;color:#888;margin:6px 0 0;">* Blogiausiu atveju = klientas pasirenka N× brangiausią konservą. Jei čia žalia — saugu bet kokiam pasirinkimui.</p>';
                        html += '</div></div>';
                    }
                    html += '</div>';
                    box.innerHTML = html;
                    gbox.appendChild(box);
                });

                // + gramatūra grupei (tik su gramatūromis)
                if (!noGram) {
                    var addGramBtn = document.createElement('button');
                    addGramBtn.type = 'button';
                    addGramBtn.className = 'button pcf-add-gram';
                    addGramBtn.setAttribute('data-gp', gpi);
                    addGramBtn.textContent = '+ Pridėti gramatūrą grupei';
                    addGramBtn.style.marginTop = '4px';
                    gbox.appendChild(addGramBtn);
                }

                groupsContainer.appendChild(gbox);
            });
            attachEvents();
            updateCreateBtn();
            renderAddButtons();
        }

        function attachEvents(){
            var C = groupsContainer;
            // Trinti grupę
            C.querySelectorAll('.pcf-del-group').forEach(function(b){
                b.onclick = function(){ if(confirm('Pašalinti visą grupę?')){ groups.splice(parseInt(this.dataset.gp),1); render(); } };
            });
            // Grupės filtras (tipas)
            C.querySelectorAll('.pcf-gfilter').forEach(function(b){
                b.onclick = function(){ groups[parseInt(this.dataset.gp)].filter = this.dataset.filter; render(); };
            });
            // Grupės sandėlio filtras
            C.querySelectorAll('.pcf-gwh').forEach(function(b){
                b.onclick = function(){ groups[parseInt(this.dataset.gp)].warehouse = this.dataset.wh; render(); };
            });
            // Pridėti gramatūrą grupei
            C.querySelectorAll('.pcf-add-gram').forEach(function(b){
                b.onclick = function(){
                    var gp = parseInt(this.dataset.gp);
                    var gram = prompt('Gramatūra (tik skaičius, pvz. 400):', '');
                    if (!gram || !/^\d+$/.test(gram)) return;
                    if (groups[gp].gramaturos.some(function(x){return x.gram===gram;})) { alert('Tokia gramatūra grupėje jau yra.'); return; }
                    groups[gp].gramaturos.push({ gram:gram, sizes:[{size:6,price:0},{size:12,price:0}], pool:[] });
                    render();
                };
            });
            // Trinti gramatūrą
            C.querySelectorAll('.pcf-del-gram').forEach(function(b){
                b.onclick = function(){
                    var gp=parseInt(this.dataset.gp), gi=parseInt(this.dataset.gi);
                    if (groups[gp].gramaturos.length<=1) { alert('Grupėje turi likti bent viena gramatūra.'); return; }
                    groups[gp].gramaturos.splice(gi,1); render();
                };
            });
            // Dydžio qty/price
            C.querySelectorAll('.pcf-size-qty').forEach(function(inp){
                inp.onchange = function(){ groups[this.dataset.gp].gramaturos[this.dataset.gi].sizes[this.dataset.si].size = parseInt(this.value)||1; render(); };
            });
            C.querySelectorAll('.pcf-size-price').forEach(function(inp){
                inp.onchange = function(){ groups[this.dataset.gp].gramaturos[this.dataset.gi].sizes[this.dataset.si].price = parseFloat(this.value)||0; render(); };
            });
            C.querySelectorAll('.pcf-add-size').forEach(function(b){
                b.onclick = function(){ groups[this.dataset.gp].gramaturos[this.dataset.gi].sizes.push({size:15,price:0}); render(); };
            });
            C.querySelectorAll('.pcf-del-size').forEach(function(b){
                b.onclick = function(){ groups[this.dataset.gp].gramaturos[this.dataset.gi].sizes.splice(parseInt(this.dataset.si),1); render(); };
            });
            C.querySelectorAll('.pcf-del-pool').forEach(function(b){
                b.onclick = function(){ groups[this.dataset.gp].gramaturos[this.dataset.gi].pool.splice(parseInt(this.dataset.ci),1); render(); };
            });
            // Paieška + "Rodyti visus tinkamus" (grupės filtras + sandėlis)
            function runPoolSearch(gp, gi, term, browse, resultsBox, inp){
                var gram = noGram ? '' : groups[gp].gramaturos[gi].gram; // v13: be-gramatūros nesiunčia 'std'
                var filter = groups[gp].filter || '';
                var warehouse = groups[gp].warehouse || '';
                var sourceCat = document.getElementById('pcf-source-cat').value;
                var url = ajaxurl+'?action=petshop_choice_search&nonce='+nonce
                    +'&term='+encodeURIComponent(term)+'&gramatura='+encodeURIComponent(gram)
                    +'&filter='+encodeURIComponent(filter)+'&warehouse='+encodeURIComponent(warehouse)
                    +'&source_cat='+encodeURIComponent(sourceCat)+(browse?'&browse=1':'');
                resultsBox.innerHTML='<div style="padding:8px;color:#999;">Kraunama...</div>'; resultsBox.style.display='block';
                fetch(url).then(function(r){return r.json();}).then(function(data){
                    var poolArr = groups[gp].gramaturos[gi].pool;
                    var avail = data.filter(function(p){ return !poolArr.some(function(c){return c.id===p.id;}); });
                    resultsBox.innerHTML='';
                    if(!data.length){ resultsBox.innerHTML='<div style="padding:8px;color:#999;">Nerasta</div>'; resultsBox.style.display='block'; return; }
                    if(browse){
                        var bar=document.createElement('div');
                        bar.style.cssText='padding:8px 12px;position:sticky;top:0;background:#f0f6fc;border-bottom:1px solid #cfe2f3;display:flex;gap:10px;align-items:center;flex-wrap:wrap;';
                        bar.innerHTML='<label style="font-size:12px;"><input type="checkbox" class="pcf-chk-all"> Pažymėti visus</label>'
                            +'<button type="button" class="button button-primary pcf-add-checked" style="font-size:12px;height:auto;padding:2px 10px;">➕ Pridėti pažymėtus</button>'
                            +'<button type="button" class="button pcf-browse-close" style="font-size:12px;height:auto;padding:2px 10px;">✕ uždaryti</button>'
                            +'<span style="font-size:11px;color:#666;">('+avail.length+' tinkamų, dar nepridėtų)</span>';
                        resultsBox.appendChild(bar);
                    }
                    data.forEach(function(p){
                        var already = poolArr.some(function(c){return c.id===p.id;});
                        var div=document.createElement('div');
                        div.style.cssText='padding:6px 12px;border-bottom:1px solid #eee;'+(already?'opacity:0.45;':'');
                        var info='<div style="font-size:13px;">'+p.text+'</div><div style="font-size:11px;color:#666;">Kaina: '+p.price.toFixed(2)+'€ | Savikaina: '+(p.cost!==null?p.cost.toFixed(2)+'€':'nėra')+' | '+p.gramatura+'</div>';
                        if(browse){
                            div.style.display='flex'; div.style.alignItems='center'; div.style.gap='8px';
                            var cb = already ? '<span style="width:16px;text-align:center;color:#2a8;">✓</span>' : '<input type="checkbox" class="pcf-chk">';
                            div.innerHTML = cb + '<div style="flex:1;">'+info+'</div>' + (already?'<span style="font-size:11px;color:#2a8;">pridėta</span>':'<button type="button" class="button pcf-add-one" style="font-size:11px;height:auto;padding:1px 8px;">+</button>');
                            div._p = p; div._already = already;
                            if(!already){ div.querySelector('.pcf-add-one').onclick=function(){ poolArr.push(p); render(); }; }
                        } else {
                            div.style.cursor = already?'default':'pointer';
                            div.innerHTML = info;
                            if(!already){ div.onclick=function(){ poolArr.push(p); resultsBox.style.display='none'; if(inp) inp.value=''; render(); }; }
                        }
                        resultsBox.appendChild(div);
                    });
                    resultsBox.style.display='block';
                    if(browse){
                        var chkAll=resultsBox.querySelector('.pcf-chk-all');
                        if(chkAll) chkAll.onchange=function(){ var ck=this.checked; resultsBox.querySelectorAll('.pcf-chk').forEach(function(c){c.checked=ck;}); };
                        var closeBtn=resultsBox.querySelector('.pcf-browse-close');
                        if(closeBtn) closeBtn.onclick=function(){ resultsBox.style.display='none'; };
                        var addBtn=resultsBox.querySelector('.pcf-add-checked');
                        if(addBtn) addBtn.onclick=function(){
                            var added=0;
                            resultsBox.querySelectorAll('.pcf-chk:checked').forEach(function(c){
                                var row=c.parentNode; var p=row._p;
                                if(p && !poolArr.some(function(x){return x.id===p.id;})){ poolArr.push(p); added++; }
                            });
                            if(added){ render(); } else { alert('Nepažymėta nė vieno naujo.'); }
                        };
                    }
                });
            }
            C.querySelectorAll('.pcf-search').forEach(function(inp){
                var gp = parseInt(inp.dataset.gp), gi = parseInt(inp.dataset.gi);
                var resultsBox = C.querySelector('.pcf-search-results[data-gp="'+inp.dataset.gp+'"][data-gi="'+inp.dataset.gi+'"]');
                var timer;
                inp.oninput = function(){
                    clearTimeout(timer);
                    var val = this.value.trim();
                    if (val.length<2){ resultsBox.style.display='none'; return; }
                    timer = setTimeout(function(){ runPoolSearch(gp, gi, val, false, resultsBox, inp); }, 300);
                };
            });
            C.querySelectorAll('.pcf-browse').forEach(function(b){
                b.onclick = function(){
                    var gp=parseInt(this.dataset.gp), gi=parseInt(this.dataset.gi);
                    var resultsBox = C.querySelector('.pcf-search-results[data-gp="'+this.dataset.gp+'"][data-gi="'+this.dataset.gi+'"]');
                    runPoolSearch(gp, gi, '', true, resultsBox, null);
                };
            });
        }

        function updateCreateBtn(){
            var title = document.getElementById('pcf-title').value.trim();
            var sku = document.getElementById('pcf-sku').value.trim();
            // Bent viena grupė su bent viena gramatūra, kuri turi pool + bent vieną kainą
            var hasValid = groups.some(function(grp){
                return grp.gramaturos.some(function(g){ return g.pool.length>0 && g.sizes.some(function(s){return s.price>0;}); });
            });
            createBtn.disabled = !(title && sku && hasValid);
        }
        document.getElementById('pcf-title').oninput = updateCreateBtn;
        document.getElementById('pcf-sku').oninput = updateCreateBtn;

        createBtn.onclick = function(){
            createBtn.disabled = true;
            statusEl.textContent = 'Kuriama...'; statusEl.style.color='#666';
            var payload = {
                title: document.getElementById('pcf-title').value.trim(),
                sku: document.getElementById('pcf-sku').value.trim(),
                category: document.getElementById('pcf-category').value,
                short_description: document.getElementById('pcf-short-desc').value.trim(),
                image_id: document.getElementById('pcf-image-id').value || '',
                no_gram: noGram ? 1 : 0,
                group_label: (document.getElementById('pcf-group-label') ? document.getElementById('pcf-group-label').value.trim() : ''),
                groups: {}
            };
            groups.forEach(function(grp){
                var gramOut = {};
                grp.gramaturos.forEach(function(g){
                    var sizes = {};
                    g.sizes.forEach(function(s){ if(s.price>0) sizes[s.size]=s.price; });
                    if(Object.keys(sizes).length && g.pool.length){
                        gramOut[g.gram] = { pool: g.pool.map(function(c){return c.id;}), sizes: sizes };
                    }
                });
                if (Object.keys(gramOut).length){
                    payload.groups[grp.key] = { label: grp.label, filter: grp.filter||'', gramaturos: gramOut };
                }
            });
            if (!Object.keys(payload.groups).length){ statusEl.textContent='❌ Nėra pilnų grupių (reikia pool + kaina).'; statusEl.style.color='#c00'; createBtn.disabled=false; return; }

            var fd = new FormData();
