// Petshop Choice — krepšelio elgsena
// Sutvarko paslėptų MnM produktų rodymą: pavadinimą (be "(paslėptas)"), redirect į krepšelį.

// === 1. Krepšelyje ir visur — pašalinam "(paslėptas)" iš pavadinimo ===
add_filter('woocommerce_cart_item_name', function($name, $cart_item, $cart_item_key) {
    // Jei pavadinime yra "(paslėptas)" — nuvalom
    if (strpos($name, '(paslėptas)') !== false || strpos($name, 'paslėptas') !== false) {
        // Ištraukiam grynąjį tekstą iš linko
        $clean = preg_replace('/\s*\(paslėptas\)\s*/u', '', $name);
        return $clean;
    }
    return $name;
}, 20, 3);

// === 2. Produkto pavadinimas visur (get_name) paslėptiems ===
add_filter('the_title', function($title, $post_id = 0) {
    if (strpos($title, '(paslėptas)') !== false) {
        return preg_replace('/\s*\(paslėptas\)\s*/u', '', $title);
    }
    return $title;
}, 20, 2);

add_filter('woocommerce_product_title', function($title, $product) {
    if (strpos($title, '(paslėptas)') !== false) {
        return preg_replace('/\s*\(paslėptas\)\s*/u', '', $title);
    }
    return $title;
}, 20, 2);

// === 3. Po pridėjimo į krepšelį — redirect į krepšelį (ne į paslėptą produktą) ===
add_filter('woocommerce_add_to_cart_redirect', function($url) {
    // Jei pridėtas choice paslėptas produktas — vedam į krepšelį
    if (isset($_REQUEST['add-to-cart'])) {
        $pid = absint($_REQUEST['add-to-cart']);
        $p = wc_get_product($pid);
        if ($p && strpos($p->get_name(), 'paslėptas') !== false) {
            return wc_get_cart_url();
        }
    }
    return $url;
}, 20);

// === 4. Krepšelio pranešimas — pavadinimą be "(paslėptas)" ===
add_filter('wc_add_to_cart_message_html', function($message, $products) {
    if (strpos($message, '(paslėptas)') !== false) {
        return preg_replace('/\s*\(paslėptas\)\s*/u', '', $message);
    }
    return $message;
}, 20, 2);

// === 5. MnM krepšelio tekstų vertimas (Edit selections) ===
// Pirma bandom gettext (jei MnM naudoja standartinį vertimą)
add_filter('gettext', function($translated, $text, $domain) {
