add_action('wp_loaded', function(){
	if(!isset($_GET['ps_rink2'])||$_GET['ps_rink2']!=='S2Kw8Nx'){return;}
	@set_time_limit(180);
	global $wpdb; $pf=$wpdb->prefix; $o=array();
	// TIKSLESNE logika: seni migrave rinkiniai
	// Kriterijai: (simple tipas) IR (kategorija rinkiniai ARBA pavadinimas su rinkinys/komplekt/KOMP prefiksu/dovanu rinkinys)
	// NEISKAITANT Mix and Match (nauji plugin rinkiniai)
	$rink_cat_ids=array(679,682,683,684);
	$in=implode(',',$rink_cat_ids);
	// visi kandidatai
	$cands=$wpdb->get_col("
		SELECT DISTINCT p.ID FROM {$pf}posts p
		WHERE p.post_type='product' AND p.post_status IN ('publish','draft','private','pending')
		AND (
			EXISTS (SELECT 1 FROM {$pf}term_relationships tr JOIN {$pf}term_taxonomy tt ON tt.term_taxonomy_id=tr.term_taxonomy_id WHERE tr.object_id=p.ID AND tt.taxonomy='product_cat' AND tt.term_id IN ($in))
			OR p.post_title LIKE '%rinkin%'
			OR p.post_title LIKE '%komplekt%'
			OR p.post_title LIKE 'KOMP%'
		)
	");
	$rows=array(); $stats=array('mix_and_match'=>0,'simple_su_likuciu'=>0,'simple_be_likucio'=>0,'kita'=>0);
	foreach($cands as $pid){
		$p=get_post($pid);
		$tt=wp_get_object_terms($pid,'product_type',array('fields'=>'names'));
		$ptype=(!is_wp_error($tt)&&!empty($tt))?$tt[0]:'simple';
		$title=html_entity_decode($p->post_title);
		// Mix and Match = naujas plugin rinkinys, NELIESTI
		if($ptype==='Mix and Match'){ $stats['mix_and_match']++; continue; }
		$sku=get_post_meta($pid,'_sku',true);
		$stock=get_post_meta($pid,'_stock',true);
		$stock_status=get_post_meta($pid,'_stock_status',true);
		$manage=get_post_meta($pid,'_manage_stock',true);
		$price=get_post_meta($pid,'_price',true);
		$regular=get_post_meta($pid,'_regular_price',true);
		$cats=wp_get_object_terms($pid,'product_cat',array('fields'=>'names'));
		$catstr=is_wp_error($cats)?'':implode(', ',array_slice($cats,0,3));
		$in_rink_cat=false;
		if(!is_wp_error($cats)){ foreach(wp_get_object_terms($pid,'product_cat',array('fields'=>'ids')) as $cid){ if(in_array($cid,array(679,682,683,684)))$in_rink_cat=true; } }
		$stock_num=is_numeric($stock)?(float)$stock:0;
		if($stock_num>0)$stats['simple_su_likuciu']++; else $stats['simple_be_likucio']++;
		$rows[]=array(
			'pid'=>$pid,'title'=>$title,'sku'=>$sku,'type'=>$ptype,'status'=>$p->post_status,
			'stock'=>$stock,'stock_num'=>$stock_num,'stock_status'=>$stock_status,'manage_stock'=>$manage,
			'price'=>$price,'regular_price'=>$regular,'cats'=>$catstr,'in_rinkiniai_cat'=>$in_rink_cat?'TAIP':'ne',
			'url'=>get_permalink($pid),
		);
	}
	// rusiuojam: pirma su likuciu, pagal statusa
	usort($rows,function($a,$b){ return $b['stock_num']<=>$a['stock_num']; });
	$o['stats']=$stats;
	$o['total_seni_rinkiniai']=count($rows);
	$o['rows']=$rows;
	header('Content-Type: application/json'); echo json_encode($o); exit;
});

