		WHERE p.post_type='product' AND p.post_status IN ('publish','draft','private','pending')
		AND (
			EXISTS (SELECT 1 FROM {$pf}term_relationships tr JOIN {$pf}term_taxonomy tt ON tt.term_taxonomy_id=tr.term_taxonomy_id WHERE tr.object_id=p.ID AND tt.taxonomy='product_cat' AND tt.term_id IN ($in))
			OR p.post_title LIKE '%rinkin%' OR p.post_title LIKE '%komplekt%' OR p.post_title LIKE 'KOMP%'
		)
	");
	$rows=array();
	foreach($cands as $pid){
		$p=get_post($pid);
		$tt=wp_get_object_terms($pid,'product_type',array('fields'=>'names'));
		$ptype=(!is_wp_error($tt)&&!empty($tt))?$tt[0]:'simple';
		if($ptype==='Mix and Match') continue; // nauji - praleidziam
		$title=html_entity_decode($p->post_title);
		// klasifikacija: maisto/skanestu rinkinys vs ne-maisto (zaislai/prieziura)
		$is_food=preg_match('/konserv|skanest|maist|pašar|pasar|kramtal|guliaš|malt|mėsos|mesos/iu',$title);
		$is_nonfood=preg_match('/žaisl|zaisl|dubenėl|dubenel|dantų|dantu|siurbl|guolis|burnos|kailio|durel/iu',$title);
		$klase=$is_nonfood?'NE-MAISTAS':($is_food?'MAISTAS':'NEAISKU');
		// bundle plugin duomenys? (Product Bundles / WPC / petshop-core komponentai)
		$bundle_data=get_post_meta($pid,'_bundle_data',true);
		$wpc_bundle=get_post_meta($pid,'_wpc_product_bundles',true);
		$petshop_components=get_post_meta($pid,'_petshop_bundle_items',true);
		$has_components=(!empty($bundle_data)||!empty($wpc_bundle)||!empty($petshop_components))?'TAIP':'ne';
		$rows[]=array(
			'pid'=>$pid,'title'=>$title,
			'sku'=>get_post_meta($pid,'_sku',true),
			'type'=>$ptype,'status'=>$p->post_status,'klase'=>$klase,
			'stock'=>get_post_meta($pid,'_stock',true),
			'stock_status'=>get_post_meta($pid,'_stock_status',true),
			'manage_stock'=>get_post_meta($pid,'_manage_stock',true),
			'price'=>get_post_meta($pid,'_price',true),
			'regular_price'=>get_post_meta($pid,'_regular_price',true),
			'has_components'=>$has_components,
			'date_created'=>$p->post_date,
			'url'=>get_permalink($pid),
		);
	}
	usort($rows,function($a,$b){ 
		$sa=is_numeric($a['stock'])?(float)$a['stock']:0; $sb=is_numeric($b['stock'])?(float)$b['stock']:0;
		return $sb<=>$sa;
	});
	$o['rows']=$rows; $o['total']=count($rows);
	// klasiu suvestine
	$by_klase=array();
	foreach($rows as $r){ $by_klase[$r['klase']]=($by_klase[$r['klase']]??0)+1; }
	$o['by_klase']=$by_klase;
	header('Content-Type: application/json'); echo json_encode($o); exit;
});

