add_action('wp_loaded', function(){
  if(!isset($_GET['ps_dep218']) || $_GET['ps_dep218']!=='Dp218x') return;
  $in=json_decode(file_get_contents('php://input'),true);
  if(!$in||empty($in['files'])){ echo '{"err":"no input"}'; exit; }
  $base=WP_PLUGIN_DIR.'/petshop-core/';
  $allow=array('petshop-core.php','includes/class-pet-profile.php','includes/class-pet-dashboard.php','includes/class-pet-products.php','includes/class-pet-ui.php','includes/class-pet-notes.php','includes/class-reminders.php','includes/class-feeding-service.php','includes/class-mixed-feeding-estimator.php','petshop-core.php','assets/pet-form.js','assets/pet-profile.js','assets/account.css','assets/pet-form.css','MU:petshop-m8-food.php','MU:petshop-feeding-calc-rest.php');
  $o=array();
  foreach($in['files'] as $rel=>$b64){
    if(!in_array($rel,$allow,true)){ $o[$rel]='SKIP'; continue; }
    $p=(strpos($rel,'MU:')===0) ? (WPMU_PLUGIN_DIR.'/'.substr($rel,3)) : ($base.$rel);
    if(file_exists($p)) copy($p,$p.'.bak_20260723_s218');
    $data=base64_decode($b64);
    file_put_contents($p,$data);
    $o[$rel]=array('bytes'=>strlen($data),'sha'=>substr(hash('sha256',file_get_contents($p)),0,16));
  }
  echo json_encode($o); exit;
});

